import{_ as a,o as s,c as n,a4 as d}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"光纤、波分复用、机房布线","description":"","frontmatter":{},"headers":[],"relativePath":"networking/phy/optical.md","filePath":"networking/phy/optical.md","lastUpdated":1788475713000}'),e={name:"networking/phy/optical.md"};function l(i,t,p,r,o,c){return s(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="光纤、波分复用、机房布线" tabindex="-1">光纤、波分复用、机房布线 <a class="header-anchor" href="#光纤、波分复用、机房布线" aria-label="Permalink to &quot;光纤、波分复用、机房布线&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>数据中心机房 + 城域网 + 骨干网关键瓶颈已经不在交换机 ASIC，而在光纤容量与光模块。一根光纤靠 DWDM 可同时承载 N 条波长，每条波长走相干调制可跑 100G-800G。这一节讲光纤物理、模场、相干检测、DWDM/OTN 系统与数据中心布线实践——你读完就能听懂光表厂家讲&quot;C波段 80 波× 100G 50 GHz grid&quot;。</p><h2 id="思维链" tabindex="-1">思维链 <a class="header-anchor" href="#思维链" aria-label="Permalink to &quot;思维链&quot;">​</a></h2><p>从一根硅石玻璃到 12.8 Tbps 跨大陆链路的链路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>硅石玻璃 -&gt; 全反射 -&gt; 单模光纤 9µm 纤芯 -&gt; C波段 1.55µm 损耗最低</span></span>
<span class="line"><span>       -&gt; 激光二极管 -&gt; 调制器 PM-QPSK/16QAM -&gt; 单波长 100G/200G/400G</span></span>
<span class="line"><span>       -&gt; 通过稀疏波分 CWDM 或密波分 DWDM 合波 -&gt; 单纤 N 波长</span></span>
<span class="line"><span>       -&gt; EDFA 掺铒光纤放大器 -&gt; 中继器 ~80 km 一个</span></span>
<span class="line"><span>       -&gt; 对端解波 -&gt; 接收 LD -&gt; 相干检测 -&gt; DSP/FEC -&gt; 100G 流</span></span></code></pre></div><p>每一跳物理都有极限：光纤损耗下限 ~0.16 dB/km (1550nm)；激光器漂温每 1℃ 大约 0.05 nm；EDFA 噪声指数 NF ≥ 3 dB（量子限制）。<strong>这些常数决定了任何光纤工程的极限</strong>：你只能选不同的&quot;调制阶数 vs OSNR 接受度 vs 距离&quot;组合。</p><h2 id="光纤类型" tabindex="-1">光纤类型 <a class="header-anchor" href="#光纤类型" aria-label="Permalink to &quot;光纤类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>纤芯直径</th><th>模式数</th><th>衰减（@850/1310/1550 nm）</th><th>距离</th><th>用途</th></tr></thead><tbody><tr><td>OM1</td><td>62.5 µm</td><td>多模</td><td>3.5 / - / - dB/km</td><td>33 m@10G</td><td>老 OM1 卡</td></tr><tr><td>OM3</td><td>50 µm</td><td>多模 LZ</td><td>3.5 / 1.5 / - dB/km</td><td>300 m@10G</td><td>机架间</td></tr><tr><td>OM4</td><td>50 µm</td><td>多模 LZ</td><td>3.0 / 1.0 / - dB/km</td><td>400 m@10G / 100m@100G</td><td>数据中心</td></tr><tr><td>OM5</td><td>50 µm</td><td>多模Wideband</td><td>3.0 / 0.5 / - dB/km</td><td>100m@100G/SWDM4</td><td>新代数据中心</td></tr><tr><td>OS2</td><td>9 µm</td><td>单模</td><td>- / 0.4 / 0.2 dB/km</td><td>10 km-1000km</td><td>城域</td></tr><tr><td>超低损单模</td><td>9 µm</td><td>单模</td><td>- / - / 0.16 dB/km</td><td>数千 km</td><td>海底</td></tr></tbody></table><p>多模 → 模色散严重（不同模式光程差），距离短。<strong>单模纵向单模传输</strong> → 数千 km。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>&quot;多模 vs 单模&quot;指的是<strong>纤芯是否大到能让多个电磁模式同时存在</strong>——直径 vs 波长量级决定模数。9 µm 纤芯 + 1.55 µm 波长约 6:1，纤芯只能支撑基模（LP01），单模传输成立。50 µm 多模则可支持数百个高阶模 → 模间群速度差就是色散漂移。</p></div><h3 id="损耗曲线与-c-波段" tabindex="-1">损耗曲线与 C 波段 <a class="header-anchor" href="#损耗曲线与-c-波段" aria-label="Permalink to &quot;损耗曲线与 C 波段&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>衰减(dB/km)</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>0.6|--        O    C        L</span></span>
<span class="line"><span>0.4|        / \\  / \\       / \\</span></span>
<span class="line"><span>0.2|       /   v    v_____/</span></span>
<span class="line"><span>    ——|———————|————————|————————|</span></span>
<span class="line"><span>       1310    1550   1625  λ (nm)</span></span></code></pre></div><ul><li><strong>O 波段 1310 nm</strong>：色散最小（零色散点），短距数据中心单模接入</li><li><strong>C 波段 1530-1565 nm</strong>：损耗最低（掺铒光纤放大器 EDFA 在此工作）→ 骨干主力</li><li><strong>L 波段 1565-1625 nm</strong>：可向下扩展容量</li><li><strong>U 波段 1625-1675 nm</strong>：监控用，正常流量不走这里</li></ul><p>EDFA 不需光电转换直接放大光，是 1990 年代起的骨干网廉价化基石。每段 EDFA 增益 ~20 dB，噪声指数 ≈ 4-5 dB。</p><hr><h2 id="dwdm-dense-wavelength-division-multiplexing" tabindex="-1">DWDM（Dense Wavelength Division Multiplexing） <a class="header-anchor" href="#dwdm-dense-wavelength-division-multiplexing" aria-label="Permalink to &quot;DWDM（Dense Wavelength Division Multiplexing）&quot;">​</a></h2><p>C 波段可以并行塞 ~80-160 个波长，间隔 50 GHz 或 100 GHz。ITU G.694.1 规定：</p><ul><li>100 GHz grid: 191.10, 191.20, ..., 196.10 THz（共 50 个波长）</li><li>50 GHz grid: 50 个之间加 50 个 → 共 96 个</li><li>37.5 GHz / 25 GHz grid：现代 flex-grid ROADM 用</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       EDFA    EDFA    EDFA    EDFA</span></span>
<span class="line"><span>光纤 -==-----==-----==-----==-----==---&gt;</span></span>
<span class="line"><span>       ^      ^      ^      ^</span></span>
<span class="line"><span>   80λ 80λ ...汇集到一根单模</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>   50 GHz ITU slot, 加 EDFA 同时放大所有波长</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>   每 80-100 km 一个 EDFA + Optical ROADM</span></span>
<span class="line"><span>   1000-2000 km 后做光电再生 (3R Regeneration)</span></span></code></pre></div><p>每个波长由独立激光器+调制器发出，复用后用同一根光纤。到对端解复用。</p><h3 id="roadms-reconfigurable-optical-add-drop-multiplexer" tabindex="-1">ROADMs（Reconfigurable Optical Add-Drop Multiplexer） <a class="header-anchor" href="#roadms-reconfigurable-optical-add-drop-multiplexer" aria-label="Permalink to &quot;ROADMs（Reconfigurable Optical Add-Drop Multiplexer）&quot;">​</a></h3><ul><li>老式 OADM：固定波长上下路，调整链路必须改硬件</li><li>ROADM：用 WSS (Wavelength Selective Switch) 软件定义任一波长上下路 → 自愈光环</li><li>现代 CDC-F ROADM (Colorless/Directionless/Contentionless/Flex-grid)：每个上下路端口任意选波长、任意方向、能映射到任意 grid → 全自动跨域光调度</li></ul><hr><h2 id="相干检测与高阶调制" tabindex="-1">相干检测与高阶调制 <a class="header-anchor" href="#相干检测与高阶调制" aria-label="Permalink to &quot;相干检测与高阶调制&quot;">​</a></h2><p>直接检测（DD）无法解码相位调制。相干检测：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本地激光 (LO) + 接收信号 → 90° 混合 (Hybrid) → 四路光电流</span></span>
<span class="line"><span>       → 数字信号处理（DSP）恢复幅度 + 相位</span></span></code></pre></div><p>调制格式：</p><table tabindex="0"><thead><tr><th>调制</th><th>bits/sym (单偏振)</th><th>加偏振复用后 bit/sym</th><th>比特/Hz</th></tr></thead><tbody><tr><td>NRZ</td><td>1</td><td>2</td><td>1</td></tr><tr><td>DP-QPSK</td><td>2</td><td>4</td><td>2</td></tr><tr><td>DP-16QAM</td><td>4</td><td>8</td><td>4</td></tr><tr><td>DP-64QAM</td><td>6</td><td>12</td><td>6</td></tr><tr><td>DP-256QAM</td><td>8</td><td>16</td><td>8</td></tr></tbody></table><p>5G 数字相干光模块功耗大（10 W+），DSP 占大头（&gt;50% 功耗），所以 400G+ 模块散热设计是数据中心产品差异化重点。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>PAM4 调制</strong>（4-level Pulse Amplitude Modulation）= 1/2 比特/符号的强度调制，DSP 极简只需要判决，不需要相干接收。100G-DR4 = 4×25Gbps PAM4 多模；400G-DR4 = 4×100Gbps PAM4。PAM4 适合 100m - 10km，相干适合 80 km-3000 km。两者中间的 10-40 km 段成为开发竞态。</p></div><hr><h2 id="数据中心光模块封装" tabindex="-1">数据中心光模块封装 <a class="header-anchor" href="#数据中心光模块封装" aria-label="Permalink to &quot;数据中心光模块封装&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形式</th><th>通道数 × 单通道速率</th><th>用途</th></tr></thead><tbody><tr><td>SFP+</td><td>1 × 10G</td><td>万兆网卡/交换</td></tr><tr><td>SFP28</td><td>1 × 25G</td><td>25G 服务器接入</td></tr><tr><td>SFP56</td><td>1 × 50G PAM4</td><td>50G 接入</td></tr><tr><td>SFP-DD</td><td>2 × 50G PAM4</td><td>100G 接入 + 双 lane</td></tr><tr><td>QSFP+</td><td>4 × 10G</td><td>40G</td></tr><tr><td>QSFP28</td><td>4 × 25G</td><td>100G</td></tr><tr><td>QSFP56</td><td>4 × 50G PAM4</td><td>200G</td></tr><tr><td>QSFP-DD</td><td>8 × 50G PAM4 / 8 × 100G</td><td>400G/800G</td></tr><tr><td>OSFP</td><td>8 × 50G PAM4</td><td>400G</td></tr><tr><td>CPO (co-packaged optics)</td><td>直接绑 Switch ASIC</td><td>800G/1.6Tbps</td></tr></tbody></table><p>数据中心 Tor 到 server 25G、到 spine 100G/400G 已成主流；2024 年 800G 开始大规模部署，1.6T CPO 在 NVIDIA Quantum-X / Ultra 集群中试点。</p><h3 id="直连铜缆-vs-有源光缆-vs-光模块" tabindex="-1">直连铜缆 vs 有源光缆 vs 光模块 <a class="header-anchor" href="#直连铜缆-vs-有源光缆-vs-光模块" aria-label="Permalink to &quot;直连铜缆 vs 有源光缆 vs 光模块&quot;">​</a></h3><ul><li><strong>DAC</strong> (Direct Attach Copper)：纯铜，0.5-5 m，无源最低延迟，0.1W，机架内 ← 必选项</li><li><strong>AOC</strong> (Active Optical Cable)：有源光缆，光模块内嵌线缆，到 100m</li><li><strong>光模块</strong>：插交换机端口，外配光纤（最灵活）</li><li><strong>CPO</strong> (Co-Packaged Optics)：光模块集成进 ASIC 包内 → 1.6Tbps 时代的关键路径</li></ul><hr><h2 id="机房布线实践" tabindex="-1">机房布线实践 <a class="header-anchor" href="#机房布线实践" aria-label="Permalink to &quot;机房布线实践&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>机架内：10G/25G 铜 DAC (无源)</span></span>
<span class="line"><span>TOR 上行：100G AOC / 400G AOC（300m 内）</span></span>
<span class="line"><span>Leaf-Spine：400G AOC / MPO-12 单模光缆配多芯</span></span>
<span class="line"><span>跨机房：单模光，OTU4 100G; 或相干 400G/800G over DWDM</span></span>
<span class="line"><span>跨城域：DWDM over 单模光纤（共享一根多业务）</span></span>
<span class="line"><span>跨大陆：海底光缆，每 80-100 km 一个 EDFA + 中继器；中继器海底供直流电</span></span></code></pre></div><h3 id="leaf-spine-fat-tree-的光纤计数" tabindex="-1">Leaf-Spine fat-tree 的光纤计数 <a class="header-anchor" href="#leaf-spine-fat-tree-的光纤计数" aria-label="Permalink to &quot;Leaf-Spine fat-tree 的光纤计数&quot;">​</a></h3><p>3-tier spine-leaf 400G 双归：一个 2000 节点 PoD，每台 leaf 有 32 个 400G 口，56 台 leaf，每台 16 上行 16 下行 → 56×16×2 = 1792 条 400G；如果做 100% 东西向带宽总容 ≈ 358 Tbps 单方向。布线密度足够压垮任何走线架，所以光模块散热与标签管理是大运维痛点——每一对模块入网前要校验波长 + 温漂曲线。</p><h3 id="路径衰减预算-link-budget-算例" tabindex="-1">路径衰减预算 (Link Budget) 算例 <a class="header-anchor" href="#路径衰减预算-link-budget-算例" aria-label="Permalink to &quot;路径衰减预算 (Link Budget) 算例&quot;">​</a></h3><p>10 km 100G-ZR 单模链路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发射功率: 0 dBm</span></span>
<span class="line"><span>光纤衰减: 10 km × 0.22 dB/km = 2.2 dB</span></span>
<span class="line"><span>连接器损耗: 4 个 × 0.5 dB = 2.0 dB</span></span>
<span class="line"><span>熔接损耗: 2 个 × 0.1 dB = 0.2 dB</span></span>
<span class="line"><span>-----</span></span>
<span class="line"><span>到达接收端: 0 - 2.2 - 2.0 - 0.2 = -4.4 dBm</span></span>
<span class="line"><span>接收灵敏度: -20 dBm</span></span>
<span class="line"><span>Margin: -4.4 - (-20) = 15.6 dB  (留 5-10 dB 应付老化/温度变化)</span></span></code></pre></div><p>≤ -20 dBm 的根本启动不了——这就是为什么&quot;重启网口看看&quot;在很多光链路故障中无用。</p><hr><h2 id="真实生产事故参考" tabindex="-1">真实生产事故参考 <a class="header-anchor" href="#真实生产事故参考" aria-label="Permalink to &quot;真实生产事故参考&quot;">​</a></h2><ol><li><strong>2018 上海某 CDN</strong>：跨机房搬迁后偶发误码率升高 → 排查发现跳纤盘卷曲半径过小 (&lt;3cm) → 弯曲损耗加 5 dB → 接收灵敏度下界触发丢弃。教训：<strong>所有跳纤必须有曲率半径规范 (≥3 cm)</strong>，运维 SOP 要包含光链路 OTDR 测试。</li><li><strong>2020 Google</strong>：海缆站 SSE (Single-Ended Source) 激光漂温过快，每 2 个月需要换模块；改用 Raman 放大器替代 EDFA 后温度敏感性下降。 → 教训：研发新光路方案时关注温度漂移模型。</li><li><strong>2019 AWS US-East</strong>：某次升级光模块固件后整批 40G 模块冷启动后误码率超阈。原因：新固件改变了 PMD 偏置电流算法，温升 20℃ 后漂出工作点。<strong>教训</strong>：量产光模块固件<strong>升级前必须做冷热启动循环测试</strong> (至少 100 次 -10-&gt;60℃ 的循环)。</li></ol><hr><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ol><li>单模光纤 C 波段 + EDFA + DWDM 是骨干廉价基础，开通 50 波 100G 跨大陆成为日常操作</li><li>调制从 QPSK → 16QAM 到 PAM4 一路加频谱效率 → 距离越短用越简单的调制</li><li>QSFP-DD / OSFP / CPO 是数据中心带宽增长曲线；CPO + LPO (Linear-drive Pluggable Optics) 是 22.4T 时代的赛点</li><li>光纤布线是面积、电源、热量的三重博弈：温升让 SFP 漂出工作点 → 链路抖动，必须做 OTDR + 温度监控兜底</li></ol><p>下一节 → <a href="./../ip/">IP / 路由</a></p>`,53)])])}const m=a(e,[["render",l]]);export{g as __pageData,m as default};
